<?php require_once __DIR__.'/includes/functions.php';$title='المتجر | ALAN';$where=['p.status="active"'];$params=[];if(!empty($_GET['category'])){$where[]='p.category_id=?';$params[]=(int)$_GET['category'];}if(!empty($_GET['q'])){$where[]='(p.name LIKE ? OR p.description LIKE ?)';$params[]='%'.$_GET['q'].'%';$params[]='%'.$_GET['q'].'%';}if(isset($_GET['new']))$where[]='p.is_new=1';$sort=$_GET['sort']??'new';$orders=['price_asc'=>'p.price ASC','price_desc'=>'p.price DESC','popular'=>'p.sales_count DESC','new'=>'p.created_at DESC'];$st=db()->prepare('SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE '.implode(' AND ',$where).' ORDER BY '.$orders[$sort]);$st->execute($params);$products=$st->fetchAll();$categories=db()->query('SELECT * FROM categories WHERE status="active" ORDER BY sort_order')->fetchAll();include __DIR__.'/includes/header.php';?><div class="page"><div class="page-title"><p class="eyebrow">مجموعة الآن</p><h1><?=isset($_GET['new'])?'وصل حديثاً':'اكتشفي عباياتنا'?></h1></div><form class="filters"><input name="q" value="<?=e($_GET['q']??'')?>" placeholder="بحث"><select name="category"><option value="">كل التصنيفات</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>" <?=($c['id']==($_GET['category']??''))?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select><select name="sort"><option value="new">الأحدث</option><option value="popular" <?=($sort==='popular')?'selected':''?>>الأكثر مبيعاً</option><option value="price_asc" <?=($sort==='price_asc')?'selected':''?>>السعر: الأقل</option><option value="price_desc" <?=($sort==='price_desc')?'selected':''?>>السعر: الأعلى</option></select><button>تصفية</button></form><?php if($products):?><div class="grid"><?php foreach($products as $p)include __DIR__.'/views/product-card.php';?></div><?php else:?><div class="empty">لا توجد قطع مطابقة لبحثكِ.</div><?php endif;?></div><?php include __DIR__.'/includes/footer.php';?>
